/* Reset & Base Variables */
:root {
  --bg-color: #060913;
  --surface-glass: rgba(15, 23, 42, 0.72);
  --surface-glass-border: rgba(255, 255, 255, 0.12);
  --surface-glass-hover: rgba(255, 255, 255, 0.16);
  --surface-glass-active: rgba(255, 255, 255, 0.22);
  --primary-accent: #38bdf8;
  --primary-glow: rgba(56, 189, 248, 0.45);
  --text-main: #f8fafc;
  --text-muted: #94a3b8;
  --text-dim: #64748b;
  --radius-lg: 18px;
  --radius-md: 12px;
  --radius-sm: 8px;
  --font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, 'Hiragino Sans', 'Noto Sans JP', sans-serif;
  --shadow-panel: 0 20px 45px rgba(0, 0, 0, 0.6), 0 0 1px rgba(255, 255, 255, 0.2);
  --backdrop-blur: blur(16px);
  --transition-fast: 0.18s ease;
  --transition-normal: 0.28s cubic-bezier(0.4, 0, 0.2, 1);
}

*, *::before, *::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
  user-select: none;
  -webkit-user-select: none;
  -webkit-tap-highlight-color: transparent;
}

html, body {
  width: 100%;
  height: 100%;
  overflow: hidden;
  background-color: var(--bg-color);
  color: var(--text-main);
  font-family: var(--font-family);
  font-size: 14px;
  line-height: 1.5;
  touch-action: none;
}

#root {
  width: 100%;
  height: 100%;
}

/* App Wrapper */
.app-wrapper {
  position: relative;
  width: 100vw;
  height: 100vh;
  overflow: hidden;
  background-color: var(--bg-color);
  display: flex;
  flex-direction: column;
}

/* Canvas Container & Main Canvas */
.canvas-container {
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  z-index: 1;
  overflow: hidden;
  touch-action: none;
  cursor: crosshair;
}

.main-canvas {
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  display: block;
}

/* Top Overlay: Title & Instruction */
.top-overlay {
  position: absolute;
  top: 20px;
  left: 24px;
  z-index: 10;
  display: flex;
  flex-direction: column;
  gap: 6px;
  pointer-events: none;
  max-width: calc(100vw - 110px);
}

.app-title {
  display: flex;
  align-items: center;
  gap: 10px;
  font-size: 1.35rem;
  font-weight: 700;
  letter-spacing: 0.04em;
  color: #ffffff;
  text-shadow: 0 0 20px rgba(56, 189, 248, 0.6), 0 2px 4px rgba(0, 0, 0, 0.8);
}

.app-badge {
  display: inline-block;
  font-size: 0.7rem;
  font-weight: 600;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  padding: 2px 8px;
  border-radius: 9999px;
  background: linear-gradient(135deg, rgba(56, 189, 248, 0.25), rgba(168, 85, 247, 0.25));
  border: 1px solid rgba(255, 255, 255, 0.25);
  color: #7dd3fc;
  box-shadow: 0 0 10px rgba(56, 189, 248, 0.3);
}

.instruction-text {
  font-size: 0.82rem;
  color: var(--text-muted);
  text-shadow: 0 1px 3px rgba(0, 0, 0, 0.8);
  pointer-events: none;
  line-height: 1.4;
}

/* FPS Counter */
.fps-counter {
  position: absolute;
  bottom: 20px;
  left: 24px;
  z-index: 10;
  font-size: 0.75rem;
  font-family: monospace;
  font-weight: 600;
  color: #38bdf8;
  background: rgba(15, 23, 42, 0.65);
  border: 1px solid rgba(255, 255, 255, 0.08);
  backdrop-filter: blur(8px);
  -webkit-backdrop-filter: blur(8px);
  padding: 4px 10px;
  border-radius: var(--radius-sm);
  pointer-events: none;
  letter-spacing: 0.05em;
}

/* Controls Toggle Button */
.controls-toggle-btn {
  position: absolute;
  top: 20px;
  right: 24px;
  z-index: 30;
  width: 44px;
  height: 44px;
  border-radius: var(--radius-md);
  background: var(--surface-glass);
  border: 1px solid var(--surface-glass-border);
  backdrop-filter: var(--backdrop-blur);
  -webkit-backdrop-filter: var(--backdrop-blur);
  color: var(--text-main);
  display: flex;
  align-items: center;
  justify-content: center;
  cursor: pointer;
  box-shadow: 0 6px 18px rgba(0, 0, 0, 0.4);
  transition: all var(--transition-fast);
}

.controls-toggle-btn:hover {
  background: var(--surface-glass-hover);
  border-color: rgba(255, 255, 255, 0.3);
  transform: translateY(-1px);
  box-shadow: 0 8px 22px rgba(56, 189, 248, 0.25);
}

.controls-toggle-btn:active {
  transform: scale(0.96);
}

/* Controls Floating Panel */
.controls-panel {
  position: absolute;
  top: 20px;
  right: 24px;
  width: 340px;
  max-height: calc(100vh - 40px);
  background: var(--surface-glass);
  border: 1px solid var(--surface-glass-border);
  border-radius: var(--radius-lg);
  backdrop-filter: var(--backdrop-blur);
  -webkit-backdrop-filter: var(--backdrop-blur);
  box-shadow: var(--shadow-panel);
  z-index: 25;
  display: flex;
  flex-direction: column;
  overflow-y: auto;
  overflow-x: hidden;
  transition: opacity var(--transition-normal), transform var(--transition-normal), visibility var(--transition-normal);
  transform: translateX(0) scale(1);
  opacity: 1;
  visibility: visible;
  scrollbar-width: thin;
  scrollbar-color: rgba(255, 255, 255, 0.2) transparent;
}

.controls-panel::-webkit-scrollbar {
  width: 6px;
}

.controls-panel::-webkit-scrollbar-track {
  background: transparent;
}

.controls-panel::-webkit-scrollbar-thumb {
  background: rgba(255, 255, 255, 0.2);
  border-radius: 9999px;
}

.controls-panel::-webkit-scrollbar-thumb:hover {
  background: rgba(255, 255, 255, 0.35);
}

.controls-panel.collapsed {
  opacity: 0;
  visibility: hidden;
  transform: translateX(20px) scale(0.96);
  pointer-events: none;
}

/* Panel Header (Sticky on top) */
.panel-header {
  position: sticky;
  top: 0;
  z-index: 10;
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 16px 20px 14px 20px;
  border-bottom: 1px solid rgba(255, 255, 255, 0.08);
  background: rgba(15, 23, 42, 0.92);
  backdrop-filter: var(--backdrop-blur);
  -webkit-backdrop-filter: var(--backdrop-blur);
  flex-shrink: 0;
}

.panel-title {
  font-size: 1rem;
  font-weight: 600;
  color: #ffffff;
  display: flex;
  align-items: center;
  gap: 8px;
}

.panel-close-btn {
  background: transparent;
  border: none;
  color: var(--text-muted);
  cursor: pointer;
  width: 28px;
  height: 28px;
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: var(--radius-sm);
  transition: background var(--transition-fast), color var(--transition-fast);
}

.panel-close-btn:hover {
  background: rgba(255, 255, 255, 0.1);
  color: #ffffff;
}

/* Panel Sections (Unified scroll flow, no individual scrollbars) */
.control-section {
  padding: 16px 20px;
  border-bottom: 1px solid rgba(255, 255, 255, 0.05);
  display: flex;
  flex-direction: column;
  gap: 12px;
  flex-shrink: 0;
}

.control-section:last-of-type {
  border-bottom: none;
}

.section-title {
  font-size: 0.76rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.06em;
  color: var(--text-dim);
}

/* Themes Grid */
.theme-grid {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 8px;
}

.theme-card {
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  gap: 6px;
  padding: 8px 10px;
  background: rgba(255, 255, 255, 0.04);
  border: 1px solid rgba(255, 255, 255, 0.08);
  border-radius: var(--radius-md);
  cursor: pointer;
  transition: all var(--transition-fast);
}

.theme-card:hover {
  background: rgba(255, 255, 255, 0.09);
  border-color: rgba(255, 255, 255, 0.18);
}

.theme-card.active {
  background: rgba(56, 189, 248, 0.14);
  border-color: var(--primary-accent);
  box-shadow: 0 0 12px var(--primary-glow);
}

.theme-color-preview {
  display: flex;
  align-items: center;
  gap: 4px;
}

.theme-dot {
  width: 10px;
  height: 10px;
  border-radius: 50%;
  display: inline-block;
  box-shadow: 0 0 6px rgba(0, 0, 0, 0.5);
}

.theme-name {
  font-size: 0.78rem;
  font-weight: 500;
  color: var(--text-main);
}

/* Behavior Modes Grid */
.mode-grid {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 8px;
}

.mode-btn {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 6px;
  padding: 8px 12px;
  background: rgba(255, 255, 255, 0.04);
  border: 1px solid rgba(255, 255, 255, 0.08);
  border-radius: var(--radius-md);
  color: var(--text-muted);
  font-size: 0.8rem;
  font-weight: 500;
  cursor: pointer;
  transition: all var(--transition-fast);
}

.mode-btn:hover {
  background: rgba(255, 255, 255, 0.09);
  color: var(--text-main);
}

.mode-btn.active {
  background: rgba(56, 189, 248, 0.16);
  border-color: var(--primary-accent);
  color: #ffffff;
  box-shadow: 0 0 12px var(--primary-glow);
}

/* Sliders */
.slider-group {
  display: flex;
  flex-direction: column;
  gap: 6px;
}

.slider-label-row {
  display: flex;
  justify-content: space-between;
  align-items: center;
}

.slider-label {
  font-size: 0.78rem;
  color: var(--text-muted);
}

.slider-value {
  font-size: 0.78rem;
  font-family: monospace;
  font-weight: 600;
  color: #7dd3fc;
}

.slider-input {
  width: 100%;
  height: 5px;
  -webkit-appearance: none;
  appearance: none;
  background: rgba(255, 255, 255, 0.12);
  border-radius: 9999px;
  outline: none;
  cursor: pointer;
  transition: background var(--transition-fast);
}

.slider-input::-webkit-slider-thumb {
  -webkit-appearance: none;
  appearance: none;
  width: 16px;
  height: 16px;
  border-radius: 50%;
  background: var(--primary-accent);
  cursor: pointer;
  box-shadow: 0 0 8px var(--primary-glow), 0 2px 4px rgba(0, 0, 0, 0.4);
  transition: transform var(--transition-fast);
}

.slider-input::-webkit-slider-thumb:hover {
  transform: scale(1.2);
}

.slider-input::-moz-range-thumb {
  width: 16px;
  height: 16px;
  border-radius: 50%;
  background: var(--primary-accent);
  cursor: pointer;
  border: none;
  box-shadow: 0 0 8px var(--primary-glow), 0 2px 4px rgba(0, 0, 0, 0.4);
  transition: transform var(--transition-fast);
}

.slider-input::-moz-range-thumb:hover {
  transform: scale(1.2);
}

/* Toggle Switches */
.toggle-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
}

.toggle-label {
  font-size: 0.8rem;
  color: var(--text-muted);
}

.toggle-switch {
  position: relative;
  display: inline-block;
  width: 42px;
  height: 24px;
}

.toggle-checkbox {
  opacity: 0;
  width: 0;
  height: 0;
}

.toggle-switch span {
  position: absolute;
  cursor: pointer;
  top: 0;
  left: 0;
  right: 0;
  bottom: 0;
  background-color: rgba(255, 255, 255, 0.15);
  border-radius: 24px;
  transition: var(--transition-normal);
}

.toggle-switch span::before {
  position: absolute;
  content: "";
  height: 18px;
  width: 18px;
  left: 3px;
  bottom: 3px;
  background-color: white;
  border-radius: 50%;
  transition: var(--transition-normal);
  box-shadow: 0 1px 4px rgba(0, 0, 0, 0.3);
}

.toggle-checkbox:checked + span {
  background-color: var(--primary-accent);
  box-shadow: 0 0 10px var(--primary-glow);
}

.toggle-checkbox:checked + span::before {
  transform: translateX(18px);
}

/* Action Button Row (Sticky on bottom) */
.action-btn-row {
  position: sticky;
  bottom: 0;
  z-index: 10;
  display: flex;
  gap: 10px;
  padding: 16px 20px;
  background: rgba(10, 15, 30, 0.92);
  border-top: 1px solid rgba(255, 255, 255, 0.08);
  backdrop-filter: var(--backdrop-blur);
  -webkit-backdrop-filter: var(--backdrop-blur);
  margin-top: auto;
  flex-shrink: 0;
}

.action-btn {
  flex: 1;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  padding: 10px 14px;
  font-size: 0.82rem;
  font-weight: 600;
  border-radius: var(--radius-md);
  border: 1px solid rgba(255, 255, 255, 0.1);
  background: rgba(255, 255, 255, 0.06);
  color: var(--text-main);
  cursor: pointer;
  transition: all var(--transition-fast);
}

.action-btn:hover {
  background: rgba(255, 255, 255, 0.12);
  transform: translateY(-1px);
}

.action-btn:active {
  transform: scale(0.97);
}

.action-btn.primary {
  background: linear-gradient(135deg, #0284c7, #38bdf8);
  border-color: rgba(255, 255, 255, 0.2);
  color: #ffffff;
  box-shadow: 0 4px 14px var(--primary-glow);
}

.action-btn.primary:hover {
  background: linear-gradient(135deg, #0369a1, #0ea5e9);
  box-shadow: 0 6px 18px rgba(56, 189, 248, 0.6);
}

/* Accessibility: Focus visible styling */
button:focus-visible,
input:focus-visible {
  outline: 2px solid var(--primary-accent);
  outline-offset: 2px;
}

.slider-input:focus-visible {
  outline: 2px solid var(--primary-accent);
  outline-offset: 4px;
}

.slider-input:focus-visible::-webkit-slider-thumb {
  box-shadow: 0 0 0 3px rgba(56, 189, 248, 0.5), 0 0 10px var(--primary-glow);
}

.slider-input:focus-visible::-moz-range-thumb {
  box-shadow: 0 0 0 3px rgba(56, 189, 248, 0.5), 0 0 10px var(--primary-glow);
}

.toggle-checkbox:focus-visible + span {
  outline: 2px solid var(--primary-accent);
  outline-offset: 2px;
}

/* High Contrast Mode */
@media (forced-colors: active) {
  .controls-panel,
  .theme-card,
  .mode-btn,
  .action-btn,
  .controls-toggle-btn,
  .panel-close-btn {
    border: 1px solid ButtonText;
  }

  .theme-card.active,
  .mode-btn.active,
  .action-btn.primary {
    outline: 2px solid Highlight;
  }
}

/* Responsive adjustments */
@media (max-width: 640px) {
  .top-overlay {
    top: 14px;
    left: 14px;
    max-width: calc(100vw - 74px);
  }

  .app-title {
    font-size: 1.15rem;
  }

  .instruction-text {
    font-size: 0.74rem;
  }

  .controls-toggle-btn {
    top: 14px;
    right: 14px;
    width: 40px;
    height: 40px;
  }

  .controls-panel {
    top: 10px;
    right: 10px;
    left: 10px;
    width: auto;
    max-height: calc(100vh - 20px);
  }

  .fps-counter {
    bottom: 14px;
    left: 14px;
  }
}

export type ColorThemeType = 'aurora' | 'neon' | 'sakura' | 'cosmic' | 'fire';

export type BehaviorModeType = 'follow' | 'orbit' | 'repel' | 'stream';

export interface ParticleSettings {
  count: number;
  size: number;
  speed: number;
  trailLength: number;
  connectLines: boolean;
  connectionDistance: number;
  colorTheme: ColorThemeType;
  behaviorMode: BehaviorModeType;
}

export interface ColorThemeInfo {
  id: ColorThemeType;
  name: string;
  colors: string[];
  background: string;
}

export interface CanvasPointer {
  x: number;
  y: number;
  isDown: boolean;
  isActive: boolean;
}

export interface ParticleCanvasHandle {
  triggerBurst: (x?: number, y?: number) => void;
}

export interface ParticleCanvasProps {
  settings: ParticleSettings;
  onFpsUpdate?: (fps: number) => void;
}

export interface ControlsProps {
  settings: ParticleSettings;
  onSettingsChange: (newSettings: ParticleSettings) => void;
  onBurst: () => void;
  isCollapsed: boolean;
  onToggleCollapse: () => void;
}

export const COLOR_THEMES = {
  aurora: {
    id: 'aurora',
    name: 'オーロラ',
    colors: ['#38bdf8', '#34d399', '#818cf8', '#a7f3d0'],
    background: '#060913',
  },
  neon: {
    id: 'neon',
    name: 'ネオン',
    colors: ['#f43f5e', '#ec4899', '#06b6d4', '#facc15'],
    background: '#090514',
  },
  sakura: {
    id: 'sakura',
    name: '桜吹雪',
    colors: ['#fbcfe8', '#f472b6', '#fda4af', '#ffffff'],
    background: '#130910',
  },
  cosmic: {
    id: 'cosmic',
    name: '宇宙',
    colors: ['#c084fc', '#a855f7', '#60a5fa', '#38bdf8'],
    background: '#040612',
  },
  fire: {
    id: 'fire',
    name: '紅蓮炎',
    colors: ['#fb923c', '#ef4444', '#f59e0b', '#fde047'],
    background: '#140705',
  },
} satisfies Record<ColorThemeType, ColorThemeInfo>;

export const DEFAULT_SETTINGS: ParticleSettings = {
  count: 350,
  size: 2.2,
  speed: 1.0,
  trailLength: 0.18,
  connectLines: true,
  connectionDistance: 95,
  colorTheme: 'aurora',
  behaviorMode: 'follow',
};

import {
  useEffect,
  useRef,
  useCallback,
  forwardRef,
  useImperativeHandle,
} from 'react';
import { ParticleCanvasProps, COLOR_THEMES, CanvasPointer } from './types';

export interface ParticleCanvasHandle {
  triggerBurst: (x?: number, y?: number) => void;
}

interface Particle {
  x: number;
  y: number;
  vx: number;
  vy: number;
  baseRadius: number;
  color: string;
  alpha: number;
  angle: number;
  orbitRadius: number;
  orbitSpeed: number;
}

interface BurstWave {
  x: number;
  y: number;
  radius: number;
  maxRadius: number;
  alpha: number;
  color: string;
}

const ParticleCanvas = forwardRef<ParticleCanvasHandle, ParticleCanvasProps>(
  function ParticleCanvas({ settings, onFpsUpdate }, ref) {
    const canvasRef = useRef<HTMLCanvasElement | null>(null);
    const containerRef = useRef<HTMLDivElement | null>(null);

    const pointerRef = useRef<CanvasPointer>({
      x: 0,
      y: 0,
      isDown: false,
      isActive: false,
    });

    const particlesRef = useRef<Particle[]>([]);
    const burstsRef = useRef<BurstWave[]>([]);
    const animFrameIdRef = useRef<number | null>(null);
    const lastTimeRef = useRef<number>(performance.now());
    const frameCountRef = useRef<number>(0);
    const fpsTimerRef = useRef<number>(performance.now());
    const autoFloatTimeRef = useRef<number>(0);

    // 指定色セットからランダム色を取得
    const getRandomColor = useCallback((colors: string[]): string => {
      return colors[Math.floor(Math.random() * colors.length)];
    }, []);

    // パーティクル生成/補充
    const initParticles = useCallback(
      (width: number, height: number, targetCount: number) => {
        const colors = COLOR_THEMES[settings.colorTheme].colors;
        const currentParticles = particlesRef.current;

        if (currentParticles.length < targetCount) {
          const needed = targetCount - currentParticles.length;
          for (let i = 0; i < needed; i++) {
            const angle = Math.random() * Math.PI * 2;
            const speed = (Math.random() * 1.5 + 0.5) * settings.speed;
            currentParticles.push({
              x: Math.random() * width,
              y: Math.random() * height,
              vx: Math.cos(angle) * speed,
              vy: Math.sin(angle) * speed,
              baseRadius: (Math.random() * 0.8 + 0.6) * settings.size,
              color: getRandomColor(colors),
              alpha: Math.random() * 0.5 + 0.5,
              angle: Math.random() * Math.PI * 2,
              orbitRadius: Math.random() * 140 + 40,
              orbitSpeed: (Math.random() * 0.02 + 0.01) * (Math.random() > 0.5 ? 1 : -1),
            });
          }
        } else if (currentParticles.length > targetCount) {
          particlesRef.current = currentParticles.slice(0, targetCount);
        }

        // 既存のパーティクルの色やサイズを最新設定に更新
        particlesRef.current.forEach((p) => {
          p.baseRadius = (Math.random() * 0.8 + 0.6) * settings.size;
          if (!colors.includes(p.color)) {
            p.color = getRandomColor(colors);
          }
        });
      },
      [settings.colorTheme, settings.size, settings.speed, getRandomColor]
    );

    // 衝撃波（バースト）を発生させる関数
    const triggerBurstAt = useCallback(
      (x: number, y: number) => {
        const themeColors = COLOR_THEMES[settings.colorTheme].colors;
        const burstColor = themeColors[0] || '#38bdf8';

        burstsRef.current.push({
          x,
          y,
          radius: 5,
          maxRadius: Math.min(window.innerWidth, window.innerHeight) * 0.35,
          alpha: 0.9,
          color: burstColor,
        });

        // 周囲のパーティクルを勢いよく吹き飛ばす
        particlesRef.current.forEach((p) => {
          const dx = p.x - x;
          const dy = p.y - y;
          const dist = Math.hypot(dx, dy) || 1;
          if (dist < 280) {
            const power = ((280 - dist) / 280) * 18 * settings.speed;
            p.vx += (dx / dist) * power;
            p.vy += (dy / dist) * power;
          }
        });
      },
      [settings.colorTheme, settings.speed]
    );

    // 親コンポーネントから直接呼び出せる命令的APIの提供
    useImperativeHandle(
      ref,
      () => ({
        triggerBurst: (customX?: number, customY?: number) => {
          const container = containerRef.current;
          const defaultX = pointerRef.current.isActive
            ? pointerRef.current.x
            : (container?.clientWidth ?? window.innerWidth) / 2;
          const defaultY = pointerRef.current.isActive
            ? pointerRef.current.y
            : (container?.clientHeight ?? window.innerHeight) / 2;

          triggerBurstAt(customX ?? defaultX, customY ?? defaultY);
        },
      }),
      [triggerBurstAt]
    );

    // Canvasリサイズ処理（setTransformで累積スケーリングを防止）
    const handleResize = useCallback(() => {
      const canvas = canvasRef.current;
      const container = containerRef.current;
      if (!canvas || !container) return;

      const width = container.clientWidth;
      const height = container.clientHeight;
      const dpr = Math.min(window.devicePixelRatio || 1, 2);

      canvas.width = width * dpr;
      canvas.height = height * dpr;

      const ctx = canvas.getContext('2d');
      if (ctx) {
        ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
      }

      initParticles(width, height, settings.count);
    }, [settings.count, initParticles]);

    // 設定更新に応じたパーティクル数・スタイルの追従
    useEffect(() => {
      const container = containerRef.current;
      if (container) {
        initParticles(container.clientWidth, container.clientHeight, settings.count);
      }
    }, [settings.count, settings.colorTheme, settings.size, settings.speed, initParticles]);

    // メインアニメーションループ
    useEffect(() => {
      const canvas = canvasRef.current;
      const container = containerRef.current;
      if (!canvas || !container) return;

      const ctx = canvas.getContext('2d');
      if (!ctx) return;

      let isRunning = true;

      const render = (time: number) => {
        if (!isRunning) return;

        const delta = (time - lastTimeRef.current) / 1000;
        lastTimeRef.current = time;

        // FPS計測
        frameCountRef.current += 1;
        if (time - fpsTimerRef.current >= 500) {
          const currentFps = Math.round((frameCountRef.current * 1000) / (time - fpsTimerRef.current));
          onFpsUpdate(Math.min(currentFps, 120));
          frameCountRef.current = 0;
          fpsTimerRef.current = time;
        }

        const width = container.clientWidth;
        const height = container.clientHeight;
        const currentTheme = COLOR_THEMES[settings.colorTheme];

        // トレイル描画（半透明黒で重ね塗り）
        ctx.globalCompositeOperation = 'source-over';
        ctx.fillStyle = currentTheme.background;
        ctx.globalAlpha = Math.max(0.04, Math.min(0.8, settings.trailLength));
        ctx.fillRect(0, 0, width, height);

        // 加算合成で光彩感を演出
        ctx.globalCompositeOperation = 'lighter';

        // ポインタ座標の決定（非操作時はリサージュ曲線で滑らかに自動遊泳）
        let targetX = pointerRef.current.x;
        let targetY = pointerRef.current.y;

        if (!pointerRef.current.isActive) {
          autoFloatTimeRef.current += delta * 0.7 * settings.speed;
          const t = autoFloatTimeRef.current;
          targetX = width / 2 + Math.sin(t * 1.3) * (width * 0.35);
          targetY = height / 2 + Math.cos(t * 0.9) * (height * 0.28);
        }

        const particles = particlesRef.current;
        const pCount = particles.length;

        // 物理計算 & 更新
        for (let i = 0; i < pCount; i++) {
          const p = particles[i];
          const dx = targetX - p.x;
          const dy = targetY - p.y;
          const dist = Math.hypot(dx, dy) || 1;

          // モード別挙動
          if (settings.behaviorMode === 'follow') {
            // 吸い寄せ
            const force = Math.min(dist * 0.00045 * settings.speed, 0.45);
            p.vx += (dx / dist) * force;
            p.vy += (dy / dist) * force;
          } else if (settings.behaviorMode === 'repel') {
            // 反発
            if (dist < 260) {
              const force = ((260 - dist) / 260) * 0.75 * settings.speed;
              p.vx += (dx / dist) * force;
              p.vy += (dy / dist) * force;
            }
          } else if (settings.behaviorMode === 'orbit') {
            // 周回軌道
            p.angle += p.orbitSpeed * settings.speed;
            const targetOrbitX = targetX + Math.cos(p.angle) * p.orbitRadius;
            const targetOrbitY = targetY + Math.sin(p.angle) * p.orbitRadius;
            p.vx += (targetOrbitX - p.x) * 0.02 * settings.speed;
            p.vy += (targetOrbitY - p.y) * 0.02 * settings.speed;
          } else if (settings.behaviorMode === 'stream') {
            // 流星群（斜め方向の気流＋ポインタ付近での加速）
            p.vx += 0.08 * settings.speed;
            p.vy += 0.12 * settings.speed;
            if (dist < 200) {
              p.vx += (dx / dist) * 0.3 * settings.speed;
              p.vy += (dy / dist) * 0.3 * settings.speed;
            }
          }

          // クリック中は引力を強化
          if (pointerRef.current.isDown) {
            const pressForce = Math.min(dist * 0.001 * settings.speed, 0.8);
            p.vx += (dx / dist) * pressForce;
            p.vy += (dy / dist) * pressForce;
          }

          // 減速摩擦
          p.vx *= 0.94;
          p.vy *= 0.94;

          // 速度上限
          const currentSpeed = Math.hypot(p.vx, p.vy);
          const maxSpd = 16 * settings.speed;
          if (currentSpeed > maxSpd) {
            p.vx = (p.vx / currentSpeed) * maxSpd;
            p.vy = (p.vy / currentSpeed) * maxSpd;
          }

          // 座標更新
          p.x += p.vx;
          p.y += p.vy;

          // 画面端のラップアラウンド（飛び出し防止）
          if (p.x < -30) p.x = width + 30;
          if (p.x > width + 30) p.x = -30;
          if (p.y < -30) p.y = height + 30;
          if (p.y > height + 30) p.y = -30;

          // パーティクル本体描画
          ctx.beginPath();
          ctx.arc(p.x, p.y, p.baseRadius, 0, Math.PI * 2);
          ctx.fillStyle = p.color;
          ctx.globalAlpha = p.alpha;
          ctx.fill();
        }

        // 接続線描画 (粒子数が多い場合の動的探索制御)
        if (settings.connectLines) {
          const maxDist = settings.connectionDistance;
          ctx.lineWidth = 0.75;
          const maxNeighbors = Math.max(6, Math.min(26, Math.floor(2600 / Math.max(1, pCount))));

          for (let i = 0; i < pCount; i++) {
            const p1 = particles[i];
            const maxJ = Math.min(i + maxNeighbors, pCount);
            for (let j = i + 1; j < maxJ; j++) {
              const p2 = particles[j];
              const dx = p1.x - p2.x;
              const dy = p1.y - p2.y;
              const dist = Math.hypot(dx, dy);

              if (dist < maxDist) {
                const lineAlpha = (1 - dist / maxDist) * 0.38;
                ctx.strokeStyle = p1.color;
                ctx.globalAlpha = lineAlpha;
                ctx.beginPath();
                ctx.moveTo(p1.x, p1.y);
                ctx.lineTo(p2.x, p2.y);
                ctx.stroke();
              }
            }
          }
        }

        // バースト衝撃波の描画
        const bursts = burstsRef.current;
        for (let i = bursts.length - 1; i >= 0; i--) {
          const b = bursts[i];
          b.radius += (b.maxRadius - b.radius) * 0.12 + 2;
          b.alpha *= 0.92;

          ctx.save();
          ctx.beginPath();
          ctx.arc(b.x, b.y, b.radius, 0, Math.PI * 2);
          ctx.strokeStyle = b.color;
          ctx.lineWidth = Math.max(1, (1 - b.radius / b.maxRadius) * 6);
          ctx.globalAlpha = b.alpha;
          ctx.stroke();
          ctx.restore();

          if (b.alpha < 0.03 || b.radius >= b.maxRadius * 0.98) {
            bursts.splice(i, 1);
          }
        }

        // ポインタ中心の微細な発光体
        if (pointerRef.current.isActive) {
          ctx.beginPath();
          ctx.arc(pointerRef.current.x, pointerRef.current.y, 4, 0, Math.PI * 2);
          ctx.fillStyle = '#ffffff';
          ctx.globalAlpha = 0.6;
          ctx.fill();
        }

        animFrameIdRef.current = requestAnimationFrame(render);
      };

      animFrameIdRef.current = requestAnimationFrame(render);

      return () => {
        isRunning = false;
        if (animFrameIdRef.current !== null) {
          cancelAnimationFrame(animFrameIdRef.current);
        }
      };
    }, [settings, onFpsUpdate]);

    // ウィンドウリサイズ監視
    useEffect(() => {
      handleResize();
      window.addEventListener('resize', handleResize);
      return () => {
        window.removeEventListener('resize', handleResize);
      };
    }, [handleResize]);

    // ポインターイベント群 (nativeEventのoffsetX/Yを利用してレイアウト再計算の負荷を軽減)
    const handlePointerDown = (e: React.PointerEvent<HTMLDivElement>) => {
      const x = e.nativeEvent.offsetX;
      const y = e.nativeEvent.offsetY;

      pointerRef.current = {
        x,
        y,
        isDown: true,
        isActive: true,
      };

      triggerBurstAt(x, y);
    };

    const handlePointerMove = (e: React.PointerEvent<HTMLDivElement>) => {
      pointerRef.current.x = e.nativeEvent.offsetX;
      pointerRef.current.y = e.nativeEvent.offsetY;
      pointerRef.current.isActive = true;
    };

    const handlePointerUp = () => {
      pointerRef.current.isDown = false;
    };

    const handlePointerLeave = () => {
      pointerRef.current.isDown = false;
      pointerRef.current.isActive = false;
    };

    return (
      <div
        ref={containerRef}
        className="canvas-container"
        onPointerDown={handlePointerDown}
        onPointerMove={handlePointerMove}
        onPointerUp={handlePointerUp}
        onPointerLeave={handlePointerLeave}
        onPointerCancel={handlePointerLeave}
      >
        <canvas ref={canvasRef} className="main-canvas" />
      </div>
    );
  }
);

