import { Sliders, X, Sparkles, RotateCcw } from 'lucide-react';
import {
  ControlsProps,
  COLOR_THEMES,
  ColorThemeInfo,
  BehaviorModeType,
  DEFAULT_SETTINGS,
} from './types';

const BEHAVIOR_MODES: { id: BehaviorModeType; label: string }[] = [
  { id: 'follow', label: '吸い寄せ' },
  { id: 'orbit', label: '周回軌道' },
  { id: 'repel', label: '反発分散' },
  { id: 'stream', label: '流星群' },
];

export default function Controls({
  settings,
  onSettingsChange,
  onBurst,
  isCollapsed,
  onToggleCollapse,
}: ControlsProps) {
  const updateSetting = <K extends keyof typeof settings>(
    key: K,
    value: (typeof settings)[K]
  ) => {
    onSettingsChange({
      ...settings,
      [key]: value,
    });
  };

  const handleReset = () => {
    onSettingsChange({ ...DEFAULT_SETTINGS });
  };

  const themeList: ColorThemeInfo[] = Object.values(COLOR_THEMES);

  return (
    <aside
      className={isCollapsed ? 'controls-panel collapsed' : 'controls-panel'}
      aria-label="シミュレーション設定"
    >
      <header className="panel-header">
        <h2 className="panel-title">
          <Sliders size={18} />
          設定コントロール
        </h2>
        <button
          type="button"
          className="panel-close-btn"
          onClick={onToggleCollapse}
          aria-label="設定を閉じる"
        >
          <X size={18} />
        </button>
      </header>

      {/* スクロール可能な設定項目コンテナ */}
      <div style={{ flex: 1, overflowY: 'auto' }}>
        {/* カラーテーマ選択 */}
        <section className="control-section">
          <h3 className="section-title">カラーテーマ</h3>
          <div className="theme-grid">
            {themeList.map((theme) => {
              const isActive = settings.colorTheme === theme.id;
              return (
                <button
                  key={theme.id}
                  type="button"
                  className={isActive ? 'theme-card active' : 'theme-card'}
                  onClick={() => updateSetting('colorTheme', theme.id)}
                  aria-pressed={isActive}
                >
                  <div className="theme-color-preview">
                    {theme.colors.map((c, i) => (
                      <span
                        key={i}
                        className="theme-dot"
                        style={{ backgroundColor: c }}
                      />
                    ))}
                  </div>
                  <span className="theme-name">{theme.name}</span>
                </button>
              );
            })}
          </div>
        </section>

        {/* 物理挙動モード */}
        <section className="control-section">
          <h3 className="section-title">挙動モード</h3>
          <div className="mode-grid">
            {BEHAVIOR_MODES.map((mode) => {
              const isActive = settings.behaviorMode === mode.id;
              return (
                <button
                  key={mode.id}
                  type="button"
                  className={isActive ? 'mode-btn active' : 'mode-btn'}
                  onClick={() => updateSetting('behaviorMode', mode.id)}
                  aria-pressed={isActive}
                >
                  {mode.label}
                </button>
              );
            })}
          </div>
        </section>

        {/* スライダー調整セクション */}
        <section className="control-section">
          <h3 className="section-title">パーティクル調整</h3>

          {/* 粒子数 */}
          <div className="slider-group">
            <div className="slider-label-row">
              <span className="slider-label" id="label-particle-count">粒子数</span>
              <span className="slider-value">{settings.count}個</span>
            </div>
            <input
              type="range"
              min="80"
              max="1000"
              step="20"
              value={settings.count}
              onChange={(e) => updateSetting('count', Number(e.target.value))}
              className="slider-input"
              aria-labelledby="label-particle-count"
              aria-valuemin={80}
              aria-valuemax={1000}
              aria-valuenow={settings.count}
              aria-valuetext={`${settings.count}個`}
            />
          </div>

          {/* サイズ */}
          <div className="slider-group">
            <div className="slider-label-row">
              <span className="slider-label" id="label-particle-size">粒子サイズ</span>
              <span className="slider-value">{settings.size.toFixed(1)}px</span>
            </div>
            <input
              type="range"
              min="1.0"
              max="5.5"
              step="0.1"
              value={settings.size}
              onChange={(e) => updateSetting('size', Number(e.target.value))}
              className="slider-input"
              aria-labelledby="label-particle-size"
              aria-valuemin={1.0}
              aria-valuemax={5.5}
              aria-valuenow={settings.size}
              aria-valuetext={`${settings.size.toFixed(1)}px`}
            />
          </div>

          {/* 速度 */}
          <div className="slider-group">
            <div className="slider-label-row">
              <span className="slider-label" id="label-particle-speed">移動速度</span>
              <span className="slider-value">{settings.speed.toFixed(1)}x</span>
            </div>
            <input
              type="range"
              min="0.3"
              max="2.5"
              step="0.1"
              value={settings.speed}
              onChange={(e) => updateSetting('speed', Number(e.target.value))}
              className="slider-input"
              aria-labelledby="label-particle-speed"
              aria-valuemin={0.3}
              aria-valuemax={2.5}
              aria-valuenow={settings.speed}
              aria-valuetext={`${settings.speed.toFixed(1)}倍速`}
            />
          </div>

          {/* 残光トレイル */}
          <div className="slider-group">
            <div className="slider-label-row">
              <span className="slider-label" id="label-particle-trail">残光クリア度</span>
              <span className="slider-value">
                {Math.round((1 - settings.trailLength) * 100)}%
              </span>
            </div>
            <input
              type="range"
              min="0.05"
              max="0.45"
              step="0.01"
              value={settings.trailLength}
              onChange={(e) => updateSetting('trailLength', Number(e.target.value))}
              className="slider-input"
              aria-labelledby="label-particle-trail"
              aria-valuemin={0.05}
              aria-valuemax={0.45}
              aria-valuenow={settings.trailLength}
              aria-valuetext={`${Math.round((1 - settings.trailLength) * 100)}%`}
            />
          </div>

          {/* 接続ラインのON/OFF */}
          <div className="toggle-row">
            <span className="toggle-label" id="label-toggle-lines">近接接続ライン</span>
            <label className="toggle-switch">
              <input
                type="checkbox"
                className="toggle-checkbox"
                checked={settings.connectLines}
                onChange={(e) => updateSetting('connectLines', e.target.checked)}
                aria-labelledby="label-toggle-lines"
              />
              <span />
            </label>
          </div>

          {/* 接続距離 */}
          {settings.connectLines && (
            <div className="slider-group">
              <div className="slider-label-row">
                <span className="slider-label" id="label-connection-distance">接続距離</span>
                <span className="slider-value">{settings.connectionDistance}px</span>
              </div>
              <input
                type="range"
                min="50"
                max="160"
                step="5"
                value={settings.connectionDistance}
                onChange={(e) => updateSetting('connectionDistance', Number(e.target.value))}
                className="slider-input"
                aria-labelledby="label-connection-distance"
                aria-valuemin={50}
                aria-valuemax={160}
                aria-valuenow={settings.connectionDistance}
                aria-valuetext={`${settings.connectionDistance}px`}
              />
            </div>
          )}
        </section>
      </div>

      {/* アクションボタン */}
      <footer className="action-btn-row">
        <button
          type="button"
          className="action-btn"
          onClick={handleReset}
          aria-label="設定を初期値に戻す"
        >
          <RotateCcw size={15} />
          初期値
        </button>
        <button
          type="button"
          className="action-btn primary"
          onClick={onBurst}
          aria-label="衝撃波バーストを発生させる"
        >
          <Sparkles size={15} />
          衝撃波バースト
        </button>
      </footer>
    </aside>
  );
}

import { useState, useCallback, useRef, useEffect } from 'react';
import { Sliders } from 'lucide-react';
import ParticleCanvas, { ParticleCanvasHandle } from './ParticleCanvas';
import Controls from './Controls';
import { DEFAULT_SETTINGS, ParticleSettings } from './types';

const STORAGE_KEY_CONTROLS_OPEN = 'particle_simulator_controls_open';

export default function App() {
  const [settings, setSettings] = useState<ParticleSettings>(DEFAULT_SETTINGS);
  const [isControlsOpen, setIsControlsOpen] = useState<boolean>(() => {
    try {
      const saved = localStorage.getItem(STORAGE_KEY_CONTROLS_OPEN);
      return saved !== null ? JSON.parse(saved) : true;
    } catch {
      return true;
    }
  });
  const [fps, setFps] = useState<number>(60);
  const canvasRef = useRef<ParticleCanvasHandle | null>(null);

  const handleFpsUpdate = useCallback((newFps: number) => {
    setFps(newFps);
  }, []);

  const handleBurst = useCallback(() => {
    canvasRef.current?.triggerBurst();
  }, []);

  const toggleControls = useCallback(() => {
    setIsControlsOpen((prev) => {
      const nextState = !prev;
      try {
        localStorage.setItem(STORAGE_KEY_CONTROLS_OPEN, JSON.stringify(nextState));
      } catch {
        // localStorageが利用できない環境への防御的対応
      }
      return nextState;
    });
  }, []);

  // キーボードショートカット（Space: バースト, C または H: 設定パネル切り替え）
  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
      const activeEl = document.activeElement;
      const isInputActive =
        activeEl instanceof HTMLInputElement ||
        activeEl instanceof HTMLTextAreaElement ||
        activeEl instanceof HTMLSelectElement;

      if (e.code === 'Space') {
        if (!isInputActive) {
          e.preventDefault();
          canvasRef.current?.triggerBurst();
        }
      } else if (e.key === 'c' || e.key === 'C' || e.key === 'h' || e.key === 'H') {
        if (!isInputActive) {
          e.preventDefault();
          toggleControls();
        }
      }
    };

    window.addEventListener('keydown', handleKeyDown);
    return () => {
      window.removeEventListener('keydown', handleKeyDown);
    };
  }, [toggleControls]);

  return (
    <div className="app-wrapper">
      {/* メイン描画キャンバス */}
      <ParticleCanvas
        ref={canvasRef}
        settings={settings}
        onFpsUpdate={handleFpsUpdate}
      />

      {/* 左上タイトル & ガイド表示 */}
      <header className="top-overlay">
        <h1 className="app-title">
          ネオンパーティクル
          <span className="app-badge">Interactive</span>
        </h1>
        <p className="instruction-text">
          タップ・ドラッグで粒子が吸い寄せられます。クリックまたは[Space]で衝撃波が発生します。[C]キーで設定パネルの開閉が可能です。
        </p>
      </header>

      {/* FPSインジケーター */}
      <div className="fps-counter" aria-label="描画フレームレート">
        FPS: {fps}
      </div>

      {/* パネル開閉ボタン */}
      <button
        type="button"
        className="controls-toggle-btn"
        onClick={toggleControls}
        aria-label={isControlsOpen ? '設定パネルを閉じる' : '設定パネルを開く'}
      >
        <Sliders size={20} />
      </button>

      {/* フローティングコントロールパネル */}
      <Controls
        settings={settings}
        onSettingsChange={setSettings}
        onBurst={handleBurst}
        isCollapsed={!isControlsOpen}
        onToggleCollapse={toggleControls}
      />
    </div>
  );
}
